import pandas as pd
import numpy as np
from scipy import stats

df = pd.read_csv('/app/bn_sample_10k.csv')
cols = df.columns.tolist()
n = len(df)

def partial_corr(df, x, y, z_list):
    """Compute partial correlation of x and y given z_list."""
    if len(z_list) == 0:
        r = df[[x, y]].corr().iloc[0, 1]
        return r
    # Use linear regression residuals
    from sklearn.linear_model import LinearRegression
    Z = df[z_list].values
    Xr = df[x].values.reshape(-1, 1)
    Yr = df[y].values.reshape(-1, 1)
    rx = LinearRegression().fit(Z, Xr).predict(Z)
    ry = LinearRegression().fit(Z, Yr).predict(Z)
    res_x = Xr.ravel() - rx
    res_y = Yr.ravel() - ry
    return np.corrcoef(res_x, res_y)[0, 1]

def partial_corr_test(df, x, y, z_list):
    """Test if partial correlation is zero. Returns (corr, p_value, t_stat)."""
    r = partial_corr(df, x, y, z_list)
    n = len(df)
    k = len(z_list)
    df_resid = n - k - 2
    if abs(r) >= 1.0:
        return r, 0.0, np.inf
    t = r * np.sqrt(df_resid / (1 - r**2))
    p = 2 * (1 - stats.t.cdf(abs(t), df_resid))
    return r, p, t

print("Marginal correlations:")
for i, c1 in enumerate(cols):
    for j, c2 in enumerate(cols):
        if j > i:
            r, p, t = partial_corr_test(df, c1, c2, [])
            print(f"  {c1} - {c2}: r={r:.4f}, p={p:.2e}")

print("\nPartial correlations given U:")
others = [c for c in cols if c != 'U']
for i, c1 in enumerate(others):
    for j, c2 in enumerate(others):
        if j > i:
            r, p, t = partial_corr_test(df, c1, c2, ['U'])
            print(f"  {c1} - {c2} | U: r={r:.4f}, p={p:.2e}")

print("\nPartial correlations given U and Y:")
for i, c1 in enumerate(others):
    for j, c2 in enumerate(others):
        if j > i:
            r, p, t = partial_corr_test(df, c1, c2, ['U', 'Y'])
            print(f"  {c1} - {c2} | U,Y: r={r:.4f}, p={p:.2e}")

print("\nAll conditioning sets:")
import itertools
for size in range(0, 5):
    for cond in itertools.combinations(cols, size):
        for i, c1 in enumerate(cols):
            for j, c2 in enumerate(cols):
                if j > i and c1 not in cond and c2 not in cond:
                    r, p, t = partial_corr_test(df, c1, c2, list(cond))
                    if abs(r) < 0.05 or p < 0.01:
                        pass  # quiet
                    # Report only significant ones
print("\nLooking for conditional independencies (p > 0.01):")
for size in range(0, 5):
    for cond in itertools.combinations(cols, size):
        for i, c1 in enumerate(cols):
            for j, c2 in enumerate(cols):
                if j > i and c1 not in cond and c2 not in cond:
                    r, p, t = partial_corr_test(df, c1, c2, list(cond))
                    if p > 0.01:
                        print(f"  {c1} _||_ {c2} | {cond}: r={r:.4f}, p={p:.4f}")
